// Fallback reply: runs only when the AI Agent fails, so the user never sees a raw error
const PROMPT_VERSION = "n8n-v2";
const chat = $('When chat message received').first();
const failure = JSON.stringify($input.first().json);  // the error the AI Agent reported
const loopLimit = /max iterations/i.test(failure);

return [{
  json: {
    session_id: chat.json.sessionId,
    question: chat.json.chatInput ?? "",
    answer: loopLimit
      ? "I couldn't finish this one. Please rephrase your question, or ask me to open a ticket."
      : "TierZero can't reach the AI service right now. Please try again in a minute.",
    action: loopLimit ? "loop_limit" : "error",
    tools_used: "",
    has_image: Boolean(chat.binary && Object.keys(chat.binary).length),
    prompt_version: PROMPT_VERSION,
    source: $execution.mode,
  },
}];

// Build log row: one row per answer, so the scorecard has data
const PROMPT_VERSION = "n8n-v4";                       // change this every time you edit the system message
const chat = $('When chat message received').first();
const result = $input.first().json;                    // the AI Agent's output
const steps = result.intermediateSteps ?? [];
const used = steps.filter((s) => !s.action.errored).map((s) => s.action.tool);    // tools that worked
const failed = steps.filter((s) => s.action.errored).map((s) => s.action.tool);   // tools that errored

let action = "answered";
if (used.includes("create_ticket")) action = "escalated";
else if (failed.includes("create_ticket")) action = "escalation_failed";          // never counts as resolved
else if (used.includes("decline_request")) action = "refused";
else if (used.includes("get_guided_fix")) action = "guided_fix";

return [{
  json: {
    session_id: chat.json.sessionId,
    question: chat.json.chatInput ?? "",
    answer: result.output ?? "",
    action,
    tools_used: [...used, ...failed.map((t) => t + " (failed)")].join(","),
    has_image: Boolean(chat.binary && Object.keys(chat.binary).length),
    prompt_version: PROMPT_VERSION,
    source: $execution.mode,                           // "test" in the editor, "production" otherwise
  },
}];
